[CmdletBinding()]
param([ValidateSet('Prepare','Package','Finalize')][string]$Phase='Prepare',[ValidateSet('Development','Manual')][string]$SigningMode='Development',[string]$BuildId,[string]$OutputRoot,[string]$NodeCache,[string]$InnoDirectory="${env:ProgramFiles(x86)}\Inno Setup 6",[string]$Publisher='WDB Development',[string]$NpmName='wdb-cli-local-test',[string]$License='UNLICENSED',[string]$LicenseFile,[string]$SignerThumbprint)
$ErrorActionPreference='Stop'
$root=Split-Path $PSScriptRoot -Parent
if(!$OutputRoot){$OutputRoot=Join-Path $root 'dist\release-builds'}
$OutputRoot=[IO.Path]::GetFullPath($OutputRoot).TrimEnd('\')
if(!$BuildId){if($Phase -ne 'Prepare'){throw 'BuildId is required when resuming'};$BuildId=(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N').Substring(0,8)}
if($BuildId -notmatch '^[A-Za-z0-9-]+$'){throw 'Invalid BuildId'}
$build=Join-Path $OutputRoot $BuildId;$stateFile=Join-Path $build 'build-state.json'
function Write-State($State){$State | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath $stateFile -Encoding UTF8}
function Assert-Inno($Directory,$Lock){foreach($file in $Lock.inno.files){$full=Join-Path $Directory $file.name;if(!(Test-Path -LiteralPath $full) -or (Get-FileHash -LiteralPath $full -Algorithm SHA256).Hash -ine $file.sha256){throw "Inno dependency differs from pinned $($Lock.inno.version): $($file.name)"}}}
function Signature-Record($File,$Relative,$Ownership){$signature=Get-AuthenticodeSignature -LiteralPath $File;[pscustomobject]@{path=$Relative;ownership=$Ownership;status=[string]$signature.Status;publisher=$signature.SignerCertificate.Subject;thumbprint=$signature.SignerCertificate.Thumbprint;timestampAuthority=$signature.TimeStamperCertificate.Subject;sha256=(Get-FileHash -LiteralPath $File -Algorithm SHA256).Hash.ToLowerInvariant()}}
if($Phase -eq 'Prepare'){
 if(Test-Path -LiteralPath $build){throw 'BuildId already exists; choose a new one'}
 if($SigningMode -eq 'Manual'){
  if((& git -C $root status --porcelain)){throw 'Manual release preparation requires a clean committed tree'}
  if(!$SignerThumbprint -or !$LicenseFile -or $License -eq 'UNLICENSED' -or $NpmName -eq 'wdb-cli-local-test' -or $Publisher -eq 'WDB Development'){throw 'Manual release needs confirmed package, license, publisher and signer thumbprint'}
 }
 $lock=Get-Content -LiteralPath (Join-Path $root 'packaging\windows\dependencies.json') -Raw | ConvertFrom-Json
 Assert-Inno $InnoDirectory $lock
 New-Item -ItemType Directory -Path $build,(Join-Path $build 'tools') -Force | Out-Null
 $common=Join-Path $build 'common'
 & (Join-Path $PSScriptRoot 'prepare-server-payload.ps1') -OutputDirectory $common -BuildId $BuildId -SigningMode $SigningMode -NodeCache $NodeCache -LicenseFile $LicenseFile | Out-Null
 Copy-Item -LiteralPath (Join-Path $root 'packaging\windows\wdb-server.iss'),(Join-Path $PSScriptRoot 'signature-content.js') -Destination (Join-Path $build 'tools')
 Copy-Item -LiteralPath $common -Destination (Join-Path $build 'pristine') -Recurse
 $info=Get-Content -LiteralPath (Join-Path $common 'BUILD-INFO.json') -Raw | ConvertFrom-Json
 $node=Join-Path $common 'runtime\node.exe'
 $npmArgs=@((Join-Path $PSScriptRoot 'build-cli-npm.js'),'--output',(Join-Path $build 'npm'),'--name',$NpmName,'--license',$License,'--build-id',$BuildId)
 if($SigningMode -eq 'Development'){$npmArgs+=@('--development','true')}
 if($LicenseFile){$npmArgs+=@('--license-file',[IO.Path]::GetFullPath($LicenseFile))}
 # The npm CLI comes from the build machine; the staged Node cache has no npm.
 & node.exe @npmArgs | Set-Content -LiteralPath (Join-Path $build 'npm-build.json') -Encoding UTF8
 if($LASTEXITCODE -ne 0){throw 'npm tarball build failed'}
 $freeze=@(Get-ChildItem -LiteralPath $common -Recurse -File | ForEach-Object {[ordered]@{path=$_.FullName.Substring($common.Length+1);sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant();bytes=$_.Length;sign=$_.Extension -in @('.ps1','.psm1','.exe','.dll') -and !$_.FullName.StartsWith((Join-Path $common 'runtime')+'\')}})
 $freeze | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $build 'prepare-manifest.json') -Encoding UTF8
 $plan=[ordered]@{buildId=$BuildId;signingMode=$SigningMode;expectedSigner=$SignerThumbprint;status=$(if($SigningMode -eq 'Manual'){'awaiting-payload-signatures'}else{'unsigned-development'});files=@($freeze | Where-Object sign | ForEach-Object {[ordered]@{path=('common\'+$_.path);ownership='wdb';action='Authenticode sign with timestamp before Package'}});later=@('SignedUninstaller cache generated by Package','Both final Setup.exe files after Package')}
 $plan | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $build 'signing-plan.json') -Encoding UTF8
 $plan.files | ForEach-Object {$_.path+' - '+$_.action} | Set-Content -LiteralPath (Join-Path $build 'SIGNING-PLAN.txt') -Encoding UTF8
 $state=[ordered]@{buildId=$BuildId;phase='prepared';signingMode=$SigningMode;publisher=$Publisher;npmName=$NpmName;signerThumbprint=$SignerThumbprint;version=$info.version;sourceCommit=$info.sourceCommit;sourceDirty=$info.sourceDirty;innoDirectory=$InnoDirectory;innoVersion=$lock.inno.version;toolHashes=@(Get-ChildItem -LiteralPath (Join-Path $build 'tools') -File | ForEach-Object {@{name=$_.Name;sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash}})}
 Write-State $state
 [ordered]@{buildId=$BuildId;phase='prepared';path=$build;signingPlan=(Join-Path $build 'signing-plan.json');next="build-release.ps1 -Phase Package -BuildId $BuildId"} | ConvertTo-Json
 return
}
$state=Get-Content -LiteralPath $stateFile -Raw | ConvertFrom-Json
$common=Join-Path $build 'common';$node=Join-Path $common 'runtime\node.exe'
$lock=Get-Content -LiteralPath (Join-Path $common 'DEPENDENCIES.json') -Raw | ConvertFrom-Json
$freeze=Get-Content -LiteralPath (Join-Path $build 'prepare-manifest.json') -Raw | ConvertFrom-Json
$frozenNode=@($freeze | Where-Object {$_.path -eq 'runtime\node.exe'})
if($frozenNode.Count -ne 1 -or (Get-FileHash -LiteralPath $node -Algorithm SHA256).Hash -ine $frozenNode[0].sha256){throw 'Frozen build runtime changed; do not execute it'}
foreach($file in $state.toolHashes){if((Get-FileHash -LiteralPath (Join-Path $build ('tools\'+$file.name)) -Algorithm SHA256).Hash -ine $file.sha256){throw 'Frozen build tooling changed; create a new BuildId'}}
$signatures=@()
foreach($file in $freeze){
 $original=Join-Path $build ('pristine\'+$file.path);$current=Join-Path $common $file.path
 if((Get-FileHash -LiteralPath $original -Algorithm SHA256).Hash -ine $file.sha256){throw 'Prepare baseline changed'}
 if((Get-FileHash -LiteralPath $current -Algorithm SHA256).Hash -ine $file.sha256){
  if(!$file.sign -or $state.signingMode -ne 'Manual'){throw "Frozen payload changed: $($file.path)"}
  & $node (Join-Path $build 'tools\signature-content.js') $original $current
  if($LASTEXITCODE -ne 0){throw 'Signing changed executable content'}
 }
 if($file.sign){$record=Signature-Record $current $file.path 'wdb';$signatures+=$record;if($state.signingMode -eq 'Manual' -and ($record.status -ne 'Valid' -or $record.thumbprint -ine $state.signerThumbprint -or !$record.timestampAuthority)){throw "Payload still awaits valid publisher/timestamp signature: $($file.path)"}}
 elseif($file.path -match '\.(exe|dll)$'){$signatures+=Signature-Record $current $file.path 'third-party'}
}
if(@(Get-ChildItem -LiteralPath $common -Recurse -File).Count -ne @($freeze).Count){throw 'Frozen payload contains unexpected files'}
$release=Join-Path $build ('release\'+$state.signingMode)
if($Phase -eq 'Package'){
 if($state.phase -notin @('prepared','awaiting-uninstaller-signature')){throw 'Package already consumed; use Finalize or a new BuildId'}
 Assert-Inno $state.innoDirectory $lock
 New-Item -ItemType Directory -Path $release,(Join-Path $build 'signed-uninstaller'),(Join-Path $build 'unsigned-installers') -Force | Out-Null
 . (Join-Path $common 'scripts\payload-common.ps1')
 foreach($mode in @('with-node','external-node')){
  $payload=Join-Path $build ('payloads\'+$mode)
  if(!(Test-Path -LiteralPath $payload)){
   New-Item -ItemType Directory -Path $payload -Force | Out-Null
   foreach($file in Get-ChildItem -LiteralPath $common -Recurse -File){$relative=$file.FullName.Substring($common.Length+1);if($mode -eq 'external-node' -and $relative -in @('runtime\node.exe','runtime\NODE-LICENSE.txt')){continue};$target=Join-Path $payload $relative;New-Item -ItemType Directory -Path (Split-Path $target) -Force | Out-Null;Copy-Item -LiteralPath $file.FullName -Destination $target}
   $info=Get-Content -LiteralPath (Join-Path $payload 'BUILD-INFO.json') -Raw | ConvertFrom-Json;$info.runtimeMode=$mode;$info | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $payload 'BUILD-INFO.json') -Encoding UTF8
   Write-WdbPayloadManifest $payload
  }
  $null=Test-WdbPayload $payload
  $args=@('/Qp',"/DPayload=$payload","/DProductVersion=$($state.version)","/DPublisher=$($state.publisher)","/DRuntimeMode=$mode","/DSigningMode=$($state.signingMode)","/DOutputDir=$release","/DSignedCache=$(Join-Path $build 'signed-uninstaller')",(Join-Path $build 'tools\wdb-server.iss'))
  # Close stdin: Manual mode reports a pending signing artifact instead of
  # leaving an unattended compiler waiting for a keypress.
  '' | & (Join-Path $state.innoDirectory 'ISCC.exe') @args *> (Join-Path $build "compile-$mode.log")
  if($LASTEXITCODE -ne 0){
   $pending=@(Get-ChildItem -LiteralPath (Join-Path $build 'signed-uninstaller') -Filter '*.exe' | Where-Object {(Get-AuthenticodeSignature -LiteralPath $_.FullName).Status -ne 'Valid'})
   if($state.signingMode -eq 'Manual' -and $pending.Count){$state.phase='awaiting-uninstaller-signature';Write-State $state;[ordered]@{status=$state.phase;files=@($pending.FullName);resume="build-release.ps1 -Phase Package -BuildId $BuildId"} | ConvertTo-Json;return}
   throw "Inno compilation failed: $(Join-Path $build "compile-$mode.log")"
  }
 }
 $executables=@(Get-ChildItem -LiteralPath $release -Filter '*-setup.exe');if($executables.Count -ne 2){throw 'Both installer variants are required'}
 foreach($exe in $executables){Copy-Item -LiteralPath $exe.FullName -Destination (Join-Path $build 'unsigned-installers')}
 $npm=Get-Content -LiteralPath (Join-Path $build 'npm\npm-package.json') -Raw | ConvertFrom-Json;Copy-Item -LiteralPath $npm.tarball -Destination $release
 $state.phase='packaged';Write-State $state
 [ordered]@{status='packaged';buildId=$BuildId;release=$release;signingMode=$state.signingMode;next="build-release.ps1 -Phase Finalize -BuildId $BuildId"} | ConvertTo-Json
 return
}
if($state.phase -ne 'packaged'){throw 'Finalize requires both packaged installers'}
foreach($exe in Get-ChildItem -LiteralPath $release -Filter '*-setup.exe'){
 & $node (Join-Path $build 'tools\signature-content.js') (Join-Path $build ('unsigned-installers\'+$exe.Name)) $exe.FullName
 if($LASTEXITCODE -ne 0){throw 'Installer content changed after packaging'}
 $record=Signature-Record $exe.FullName $exe.Name 'wdb-installer';$signatures+=$record
 if($state.signingMode -eq 'Manual' -and ($record.status -ne 'Valid' -or $record.thumbprint -ine $state.signerThumbprint -or !$record.timestampAuthority)){throw 'Final installers await valid publisher/timestamp signatures'}
}
foreach($exe in Get-ChildItem -LiteralPath (Join-Path $build 'signed-uninstaller') -Filter '*.exe'){$record=Signature-Record $exe.FullName ('signed-uninstaller/'+$exe.Name) 'wdb-uninstaller';$signatures+=$record;if($state.signingMode -eq 'Manual' -and ($record.status -ne 'Valid' -or $record.thumbprint -ine $state.signerThumbprint -or !$record.timestampAuthority)){throw 'Uninstaller cache signature does not match release publisher/timestamp'}}
$artifacts=@(Get-ChildItem -LiteralPath $release -File | Where-Object {$_.Extension -in @('.exe','.tgz')} | ForEach-Object {[ordered]@{name=$_.Name;bytes=$_.Length;sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}})
if(@($artifacts | Where-Object {$_.name -like '*-setup.exe'}).Count -ne 2 -or @($artifacts | Where-Object {$_.name -like '*.tgz'}).Count -ne 1){throw 'Incomplete release outputs'}
$manifest=[ordered]@{buildId=$BuildId;version=$state.version;protocolVersion=1;sourceCommit=$state.sourceCommit;sourceDirty=$state.sourceDirty;signingMode=$state.signingMode;status=$(if($state.signingMode -eq 'Development'){'development-unsigned'}else{'signed-awaiting-installation-acceptance'});releaseReady=$false;builtAt=[DateTime]::UtcNow.ToString('o');innoVersion=$state.innoVersion;nodeVersion=$lock.node.version;nodeRange='>=22.0.0';artifacts=$artifacts;payloads=@(@('with-node','external-node') | ForEach-Object {@{runtimeMode=$_;bytes=(Get-ChildItem -LiteralPath (Join-Path $build "payloads\$_") -Recurse -File | Measure-Object Length -Sum).Sum}})}
$manifest | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $release 'release-manifest.json') -Encoding UTF8
$signatures | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $release 'signing-report.json') -Encoding UTF8
$artifacts | ForEach-Object {'{0}  {1}' -f $_.sha256,$_.name} | Set-Content -LiteralPath (Join-Path $release 'SHA256SUMS.txt') -Encoding UTF8
@{buildId=$BuildId;status='installation-verification-pending';checks=@();notRun=@('macOS npm validation','clean Windows baseline','registry installation','manual publisher signing when Development')} | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $release 'verification-report.json') -Encoding UTF8
$state.phase='finalized';Write-State $state
$manifest | ConvertTo-Json -Depth 8
